#' Table of synthetic outcome significance levels.
#' 
#'@description
#' `synth_table()` Makes a summary table of estimated and placebo p values from output generated by 
#' [synth()], [synth_im()], [synth_scpc()] or [iv_synth()].
#' 
#' @param syn An object containing simulation results created by synth, synth_im, synth_scpc or iv_synth.
#' @param caption An optional caption for the table.
#' @param type For results from [iv_synth()], the table shown: `"BCH"` (the
#'   default), `"IM"`, `"SCPC"` or `"AR"`, as in [placebo_table()]. Not used for other
#'   results.
#'
#' @return Generates a tinytable object. This gives the regression and synthetic outcome p values as the number of clusters, or the SCPC bound `avc`, increases.
#'  The regression confidence interval and its width are also reported. The next part of the table gives
#'  the z-score of a Moran test, using 5 nearest neighbours, the R2 of a regression of the outcome on a
#'  quadratic in longitude and latitude, and the effective range and structure of this regression's residuals.
#' @export
#'
#' @examples
#' library(spatInfer)
#' data(opportunity)
#' # Use 100 observations and 100 simulations to speed things up.
#' set.seed(123)
#' opportunity=opportunity |> dplyr::slice_sample(n=100)
#' # Use the number of splines and PCs indicated by [optimal_basis()] and turn off parallel processing.
#' synt=synth(mobility~single_mothers+short_commute+gini+dropout_rate+social_cap+dropout_na,                                 opportunity,
#' splines=6,
#' pc_num=15,
#' nSim=100,
#' Parallel=FALSE,
#' max_clus = 7
#' )
#' synth_table(synt, caption="Synthetic outcomes significance levels for single mothers variable.")


synth_table=function(syn, caption="", type=c("BCH","IM","SCPC","AR")){
type=match.arg(type)
is_iv=is_iv_results(syn$Results)
if(is_iv) syn$Results=iv_table_rows(syn$Results,type)
syn$Results=blank_repeated_se(syn$Results)
rr=syn$Results
rr=rr |>
  dplyr::rename(Adj=SE) |> 
  dplyr::select(-dplyr::contains("_05"))|>
  dplyr::select(-dplyr::any_of("Pseudo SE")) |>   #pseudo SEs are in Results but not the table
  dplyr::mutate(dplyr::across(dplyr::where(is.numeric)&!dplyr::any_of("CI Width"),~{round(.x,3)}))   #CI widths keep their significant digits
ss=syn$Spatial_Params
ss=ss |>
  dplyr::mutate(dplyr::across(dplyr::where(is.numeric),~{round(.x,2)}))

syn_tab=tinytable::tt(rr,theme="striped",align="r",digits=3 ,
              notes=   Filter(Negate(is.null),list(
                paste0("Moran=",ss$Moran,
                       ", Structure=",ss$Structure,
                       ", Effective Range=",ss$Effective_Range,
                       ", R2=",ss$R2,"."
                ),
                paste0(
                  "N=",ss$N,
                  ", Splines=",ss$Splines,
                       ", PCs=",ss$PCs,"."
                ),
                if(is_iv) iv_notes(ss,type,"SCPC" %in% rr$Adj),
                if("avc" %in% names(rr))
                  "Estimated and synthetic outcome p values for different values of the SCPC average correlation bound avc.
                R2 gives the explanatory power of a regression of the outcome on a quadratic in longitude and latitude."
                else
                "Estimated and synthetic outcome p values for different cluster numbers.
                R2 gives the explanatory power of a regression of the outcome on a quadratic in longitude and latitude."
              )),
              caption=caption
)

syn_tab= syn_tab |>
  tinytable::style_tt(j = 1, bold=TRUE )

return(syn_tab)
}
